                        path: state.path.slice(),
                        countsArr: state.countsArr.slice(),
                        usageBits: state.usageBits.slice(),
                        ints: state.ints,
                        jumpMarks: state.jumpMarks.slice(),
                        jumpCount: state.jumpCount,
                        flipCount: state.flipCount,
