                            s.portal.portalLastProgressValue = portalCtx.progressBefore;
                            this._undoLogWrite(s, LOG_PORTAL_LAST_FAMILY, 0, Number.isFinite(s.portal?.portalLastFamily) ? s.portal?.portalLastFamily : -1);
                            s.portal.portalLastFamily = portalCtx.family;
                            this._undoLogWrite(s, LOG_PORTAL_LAST_REGION, 0, Number.isFinite(s.portal?.portalLastRegion) ? s.portal?.portalLastRegion : -1);
