            const nodesExpanded = Math.max(0, Number(result?.nodesExpanded ?? diagnostics?.nodesExpanded ?? result?.debug?.nodesExpanded) || 0);
            const candidateMovesConsidered = Math.max(0, Number(result?.candidateMovesConsidered ?? diagnostics?.candidateMovesConsidered ?? result?.debug?.branchesTried) || 0);
            const rootCandidatesGenerated = Math.max(0, Number(result?.rootCandidatesGenerated ?? rootSummary?.rootCandidatesGenerated ?? result?.debug?.rootCandidatesGenerated) || 0);
