                const nodesExpanded = Math.max(0, Number(debug?.nodesExpanded) || 0);
                const branchesTried = Math.max(0, Number(debug?.branchesTried) || 0);
                const timeline = Array.isArray(debug?.phaseTimeline) ? debug.phaseTimeline : [];
                const maxProgress = timeline.reduce((m, ev) => Math.max(m, Number(ev?.progress) || 0), 0);
                const remainingObjectives = timeline.length > 0 ? Math.max(0, Number(timeline[timeline.length - 1]?.remainingObjectives) || 0) : 0;
                const unresolvedConstraintPenalty = Math.max(0, remainingObjectives / 5);
                const frontierQuality = Math.max(0, Math.min(1, (maxProgress * 0.7) + (Math.max(0, 1 - unresolvedConstraintPenalty) * 0.2) + (Math.max(0, 1 - Math.min(1, Math.abs((branchesTried / Math.max(1, nodesExpanded)) - 0.55))) * 0.1)));
